    while not b :
        ch=str(input("< "))
        b = verif(ch)
    return ch

def verif(ch):
    ok = ch[0] != " " and ch[len(ch)-1] != " "
    i = -1
    while ok and i < len(ch)-1 :
        i += 1
        ok = ch[i] == " " or "A" <= ch[i].upper() <= "Z"
    return ok 
    
def nombre_mots(ch):
    nb = 1
    for i in range (len(ch)-1) :
        if ch[i] == " " and ch[i+1] != " " :
            nb += 1
    return nb

def crypter(ch,x):
    R = ""
    for i in range (len(ch)):
        if "A" <= chr(ord(ch[i])+x).upper() <="Z" :
            R += chr(ord(ch[i])+x)
        elif ch[i] == " " :
            R += " "
        else:
            R += chr(ord(ch[i])+x-26)
    return R

